  const {url} = await startEngineWith({sessionStore, wsAuth: async () => ({id: userId})});
  return url;
};

// The frame under test goes out on connect, followed by a ping whose pong can only come after its answer.
const askAfterConnect = async (url: string, outbound: unknown): Promise<{frames: Frame[]}> => {
  const client = connectClient(url);
  const frames: Frame[] = [];
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type === 'connected') client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
